"""Algorithm B / D — exhaustive exact certification on the residue-data space.

Algorithm B enumerates the finite residue-data space
Omega_S = prod_{p in S} Z/pZ, computes the centred dial features
x_p = dial_p - 1, and evaluates in exact rational arithmetic:

    * the design moments E[x_p], E[x_p x_q], E[x_p^2];
    * the covariance of any target with each feature;
    * the footprint energy (= recalibration ceiling) and the target variance;
    * the mean squared error of any prescribed affine predictor (c, beta).

Algorithm D computes the *pointwise optimal nonlinear* footprint model, namely
the conditional expectation of the target given the footprint half of the
residue data, and reports whether it is constant.

Complexity: O(|S| * prod_{p in S} p) exact rational operations, which is
practical while prod p is below roughly 10^7; its purpose is to certify the
O(|S|) closed forms of Algorithm A, with which it agrees exactly.
"""

from __future__ import annotations

from fractions import Fraction
from itertools import product
from typing import Callable, Dict, List, Sequence, Tuple

Residue = Tuple[int, ...]


def dial(p: int, n: int) -> int:
    """Number of square roots of n modulo the odd prime p."""
    return sum(1 for x in range(p) if (x * x - n) % p == 0)


def space(primes: Sequence[int]) -> List[Residue]:
    return [tuple(t) for t in product(*(range(p) for p in primes))]


def design_moments(primes: Sequence[int]) -> Dict[str, Fraction]:
    """Exact first and second moments of the centred dial design."""
    omega = space(primes)
    size = len(omega)
    out: Dict[str, Fraction] = {}
    for j, p in enumerate(primes):
        out[f"E[x_{p}]"] = sum(
            (Fraction(dial(p, N[j]) - 1) for N in omega), Fraction(0)
        ) / size
        out[f"E[x_{p}^2]"] = sum(
            (Fraction((dial(p, N[j]) - 1) ** 2) for N in omega), Fraction(0)
        ) / size
    for j, p in enumerate(primes):
        for k, q in enumerate(primes):
            if j < k:
                out[f"E[x_{p} x_{q}]"] = sum(
                    (
                        Fraction((dial(p, N[j]) - 1) * (dial(q, N[k]) - 1))
                        for N in omega
                    ),
                    Fraction(0),
                ) / size
    return out


def analyse(
    primes: Sequence[int], target: Callable[[Residue], Fraction]
) -> Dict[str, object]:
    """Algorithm B: exact covariances, energy, variance, zero-fit loss."""
    omega = space(primes)
    size = len(omega)
    mean = sum((target(N) for N in omega), Fraction(0)) / size
    var = sum(((target(N) - mean) ** 2 for N in omega), Fraction(0)) / size
    covs: Dict[int, Fraction] = {}
    energy = Fraction(0)
    for j, p in enumerate(primes):
        cov = sum(
            (target(N) * Fraction(dial(p, N[j]) - 1) for N in omega), Fraction(0)
        ) / size
        covs[p] = cov
        energy += cov ** 2 / Fraction(p - 1, p)
    return {"mean": mean, "variance": var, "covariances": covs, "energy": energy}


def mse(
    primes: Sequence[int],
    target: Callable[[Residue], Fraction],
    c: Fraction,
    beta: Sequence[Fraction],
) -> Fraction:
    omega = space(primes)
    total = Fraction(0)
    for N in omega:
        pred = c + sum(
            (b * Fraction(dial(p, n) - 1) for b, p, n in zip(beta, primes, N)),
            Fraction(0),
        )
        total += (target(N) - pred) ** 2
    return total / len(omega)


def optimal_nonlinear_model(
    primes: Sequence[int], footprint_size: int, target: Callable[[Residue], Fraction]
) -> Dict[Residue, Fraction]:
    """Algorithm D: conditional expectation of the target given the footprint half."""
    groups: Dict[Residue, List[Fraction]] = {}
    for N in space(primes):
        groups.setdefault(N[:footprint_size], []).append(target(N))
    return {k: sum(v, Fraction(0)) / len(v) for k, v in groups.items()}


if __name__ == "__main__":
    primes = [3, 5, 7]

    def structure_correction(N: Residue) -> Fraction:
        out = Fraction(1)
        for p, n in zip(primes, N):
            out *= Fraction(p - dial(p, n), p - 1)
        return out

    print(design_moments(primes))
    print(analyse(primes, structure_correction))
    beta_star = [Fraction(-1, p - 1) for p in primes]
    print("best refit loss:", mse(primes, structure_correction, Fraction(1), beta_star))
    print("zero-fit loss  :", mse(primes, structure_correction, Fraction(1),
                                  [Fraction(0)] * len(primes)))
